node -e 'const fs=require("fs");const fail=(m)=>{console.error("LIVE-707 FAILED: "+m);process.exit(1)}
const P="app/space-email-policy/page.tsx"
if(!fs.existsSync(P))fail("there is no Space email acceptable-use policy at app/space-email-policy/page.tsx")
const norm=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")
const body=norm(fs.readFileSync(P,"utf8"))
for(const s of ["What this covers","Who you may email","Unsubscribes","What you may not send","Sending limits","Bounces and spam complaints","When we turn email off","Asking us to look again"])if(!body.includes("title=\""+s+"\""))fail("the policy has lost a section: "+s)
if(/[–—]/.test(body))fail("the policy carries an em or en dash (CONTENT-VOICE)")
const cap=/export const DAILY_SEND_CAP = ([\d_]+)/.exec(fs.readFileSync("lib/spaces/email.ts","utf8"))
if(!cap)process.exit(79)
const n=Number(cap[1].replace(/_/g,"")).toLocaleString("en-US")
if(!body.includes("up to "+n+" emails a day"))fail("the policy states a daily limit the send backbone does not enforce (the code says "+n+")")
const cc=/const COMPLAINT_CEILING = ([\d.]+)/.exec(fs.readFileSync("components/spaces/email/analytics-panel.tsx","utf8"))
if(!cc)process.exit(79)
if(!body.includes("spam complaints go above "+(Number(cc[1])*100)+"%"))fail("the policy states a complaint line the Email panel does not warn at")
console.log("ok")'
